fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    // Precondition: a and b have the same positive length
    assert_eq!(n, b.len());
    assert!(n > 0);

    // If the length is odd, return the middle element of `a`.
    if n % 2 == 1 {
        a[n / 2]
    } else {
        // Even length: take the last element of the lower half of `a`
        // and the first element of `b`, then average them with
        // rounding down (floor division) for negative sums.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        let sum = x + y;
        let avg = if sum >= 0 {
            sum / 2
        } else {
            // For negative odd sums, (sum - 1) / 2 rounds down.
            (sum - 1) / 2
        };
        avg as i32
    }
}

